-- Sofia's Configurable Inventory (MyFirstMod) - RuneScape: Dragonwilds
-- Version 1.3.0
--
-- Features:
--   1) Configurable slots for ALL 4 Player Tabs (Main Bag, Runes, Ammo, Quest Items) AND Storage Chests
--      via Mod Menu 2.0 & config.txt.
--   2) Supports non-multiple-of-8 slot counts (steps of 4) by automatically collapsing unused trailing slot widgets
--      on the last row so they never point into adjacent pages.
--   3) Pre-copy CDO & GEN_VARIABLE template patching + state.txt high-water mark so the game's
--      HandleLoadedItemWithInvalidSlot check never drops items when shrinking tabs or disabling the mod.
--   4) Smart multi-tab item relocation (MoveItem + GameplayTag inspection + swap-deadlock breaker) that
--      automatically migrates Runes, Arrows/Bolts, Quest Items, and Regular Items into their proper tab ranges!
--   5) Storage Chest expansion & compaction: expands player-built storage containers (BP_Components_WorldItemInventory_C)
--      while safely skipping crafting/processing stations, compacts items when shrinking, and resizes the chest UI grid.
--   6) Hot-reload-safe (Ctrl+R) in-memory Weightless / Weight Scale option with shared-variable original weight caching.

local TAG = "[MyFirstMod] "
local VERSION = "1.3.0"
local MODMENU_ID = "MyFirstMod"

local function log(msg)
print(TAG .. tostring(msg) .. "\n")
end

local cfg = {
    Enabled       = true,
    BagSlots      = 96,
    RuneSlots     = 48,
    AmmoSlots     = 48,
    QuestSlots    = 72,
    ChestEnabled  = true,
    ChestSlots    = 64,
    NoWeight      = false,
    WeightScale   = 1.0,
    HideScrollBar = true,
    Hotkey        = "F9",
    Verbose       = false,
}

local function dbg(msg)
if cfg.Verbose then
    log("[DEBUG] " .. tostring(msg))
    end
    end

    -- Constants ----------------------------------------------------------------------------------------
    local COLUMNS = 8
    local BAG_MIN, BAG_MAX = 24, 160
    local TAB_MIN, TAB_MAX = 24, 96
    local CHEST_MIN, CHEST_MAX = 16, 160
    local MAX_POSSIBLE_TOTAL = 8 + BAG_MAX + TAB_MAX * 3

    local TYPE_QUICK = 0
    local TYPE_ITEMS = 1
    local TYPE_RUNES = 2
    local TYPE_AMMO  = 3
    local TYPE_QUEST = 4

    local PLAYER_INV_CLASS = "BP_Components_Inventory_C"
    local CHEST_INV_CLASS  = "BP_Components_WorldItemInventory_C"
    local BODY_CLASS       = "WBP_Inventory_InventoryBody_C"
    local VIS_VISIBLE      = 0
    local VIS_COLLAPSED    = 1

    local STATION_WORDS = {
        "craft", "recipe", "process", "smelt", "cook", "fuel", "station",
        "furnace", "sawmill", "workbench", "kiln", "loom", "tannery", "anvil", "brewing",
    }
    local CONTAINER_WORDS = { "crate", "chest", "storage", "barrel", "trunk", "coffer", "box" }

    -- Vanilla defaults (updated dynamically when templates are first inspected)
    local baseDefaults = {
        [TYPE_ITEMS] = 32,
        [TYPE_RUNES] = 24,
        [TYPE_AMMO]  = 24,
        [TYPE_QUEST] = 24,
        quick = 8,
        max = 112,
    }

    -- Helpers ------------------------------------------------------------------------------------------
    local function callIsValid(o)
    return o:IsValid()
    end

    local function valid(o)
    if not o or type(o) ~= "userdata" then return false end
        local ok, v = pcall(callIsValid, o)
        return ok and v == true
        end

        local function full(o)
        if not valid(o) then return "" end
            local ok, n = pcall(function() return o:GetFullName() end)
            return ok and tostring(n) or ""
            end

            local function pathOf(o)
            local f = full(o)
            return f:match("^%S+%s+(.+)$") or f
            end

            local function className(o)
            if not valid(o) then return "" end
                local ok, n = pcall(function() return o:GetClass():GetFName():ToString() end)
                return ok and tostring(n) or ""
                end

                local function key(o)
                local a = "?"
                pcall(function() a = string.format("%x", o:GetAddress()) end)
                return full(o) .. "@" .. a
                end

                local function isTemplate(n)
                return n:find("Default__", 1, true) ~= nil
                or n:find("GEN_VARIABLE", 1, true) ~= nil
                or n:find("_C:WidgetTree", 1, true) ~= nil
                end

                local function num(v)
                return type(v) == "number" and v or nil
                end

                local function setShared(k, v)
                if not ModRef or not ModRef.SetSharedVariable then return false end
                    return pcall(ModRef.SetSharedVariable, ModRef, k, v)
                    end

                    local function getShared(k)
                    if not ModRef or not ModRef.GetSharedVariable then return nil end
                        local ok, val = pcall(ModRef.GetSharedVariable, ModRef, k)
                        if ok then return val end
                            return nil
                            end

                            -- Safe weak reference across ticks (prevents reading freed UObject pointers after world reload)
                            local function ref(o)
                            local r = { path = pathOf(o) }
                            pcall(function() r.addr = o:GetAddress() end)
                            return r
                            end

                            local function deref(r)
                            if not r or not r.path or r.path == "" then return nil end
                                local o
                                pcall(function() o = StaticFindObject(r.path) end)
                                if not o then return nil end
                                    local a
                                    pcall(function() a = o:GetAddress() end)
                                    if a == nil or a ~= r.addr then return nil end
                                        if not valid(o) then return nil end
                                            return o
                                            end

                                            -- Config & High-Water State ------------------------------------------------------------------------
                                            local cachedModRoot = nil
                                            local function modRoot()
                                            if cachedModRoot then return cachedModRoot end
                                                local src = (debug.getinfo(1, "S").source or ""):gsub("^@", "")
                                                cachedModRoot = src:match("^(.*)[/\\]Scripts[/\\][^/\\]*$")
                                                return cachedModRoot
                                                end

                                                local function clampSlots(val, minV, maxV)
                                                local n = tonumber(val) or minV
                                                n = math.floor((n / 4) + 0.5) * 4
                                                return math.max(minV, math.min(maxV, n))
                                                end

                                                local function clampConfig()
                                                cfg.BagSlots    = clampSlots(cfg.BagSlots, BAG_MIN, BAG_MAX)
                                                cfg.RuneSlots   = clampSlots(cfg.RuneSlots, TAB_MIN, TAB_MAX)
                                                cfg.AmmoSlots   = clampSlots(cfg.AmmoSlots, TAB_MIN, TAB_MAX)
                                                cfg.QuestSlots  = clampSlots(cfg.QuestSlots, TAB_MIN, TAB_MAX)
                                                cfg.ChestSlots  = clampSlots(cfg.ChestSlots, CHEST_MIN, CHEST_MAX)
                                                cfg.WeightScale = math.floor(math.max(0.1, math.min(1.0, tonumber(cfg.WeightScale) or 1.0)) * 10 + 0.5) / 10
                                                cfg.Hotkey      = tostring(cfg.Hotkey or "F9"):upper():gsub("^%s+", ""):gsub("%s+$", "")
                                                if cfg.Hotkey == "" then cfg.Hotkey = "F9" end
                                                    end

                                                    local function loadConfig()
                                                    local root = modRoot()
                                                    if not root then
                                                        log("Could not resolve mod root folder; using defaults.")
                                                        return
                                                        end
                                                        local f = io.open(root .. "/config.txt", "r") or io.open(root .. "\\config.txt", "r")
                                                        if not f then
                                                            log("No config.txt found; using defaults.")
                                                            return
                                                            end
                                                            for line in f:lines() do
                                                                line = line:gsub("^%s+", ""):gsub("%s+$", "")
                                                                if line ~= "" and line:sub(1, 1) ~= "#" then
                                                                    local k, v = line:match("^([%w_]+)%s*=%s*(.*)$")
                                                                    v = (v or ""):gsub("%s*[#;].*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
                                                                    if k and cfg[k] ~= nil then
                                                                        if type(cfg[k]) == "boolean" then
                                                                            local w = v:lower()
                                                                            cfg[k] = (w == "true" or w == "1" or w == "yes" or w == "on")
                                                                            elseif type(cfg[k]) == "number" then
                                                                                cfg[k] = tonumber(v) or cfg[k]
                                                                                else
                                                                                    cfg[k] = v:gsub('^"(.*)"$', "%1")
                                                                                    end
                                                                                    end
                                                                                    end
                                                                                    end
                                                                                    f:close()
                                                                                    clampConfig()
                                                                                    end

                                                                                    local CONFIG_KEYS_ORDER = {
                                                                                        "Enabled", "BagSlots", "RuneSlots", "AmmoSlots", "QuestSlots",
                                                                                        "ChestEnabled", "ChestSlots", "NoWeight", "WeightScale",
                                                                                        "HideScrollBar", "Hotkey", "Verbose",
                                                                                    }

                                                                                    local function saveConfig()
                                                                                    local root = modRoot()
                                                                                    if not root then return end
                                                                                        local f = io.open(root .. "/config.txt", "w") or io.open(root .. "\\config.txt", "w")
                                                                                        if not f then return end
                                                                                            f:write("# Sofia's Configurable Inventory (MyFirstMod) Configuration\n")
                                                                                            f:write("# Slot counts support multiples of 4 (e.g. 24, 28, 32 ... 160).\n\n")
                                                                                            for _, k in ipairs(CONFIG_KEYS_ORDER) do
                                                                                                local v = cfg[k]
                                                                                                if type(v) == "string" then
                                                                                                    f:write(string.format('%s = "%s"\n', k, v))
                                                                                                    elseif type(v) == "number" and k == "WeightScale" then
                                                                                                        f:write(string.format("%s = %.1f\n", k, v))
                                                                                                        else
                                                                                                            f:write(string.format("%s = %s\n", k, tostring(v)))
                                                                                                            end
                                                                                                            end
                                                                                                            f:close()
                                                                                                            end

                                                                                                            -- state.txt tracks the highest total slots saved in the last session so loading a save after
                                                                                                            -- lowering slot sliders or turning the mod off never triggers HandleLoadedItemWithInvalidSlot.
                                                                                                            local function readSavedTotal()
                                                                                                            local root = modRoot()
                                                                                                            if not root then return nil end
                                                                                                                local f = io.open(root .. "/state.txt", "r") or io.open(root .. "\\state.txt", "r")
                                                                                                                if not f then return nil end
                                                                                                                    local v = tonumber((f:read("*a") or ""):match("SaveMaxSlots%s*=%s*(%d+)"))
                                                                                                                    f:close()
                                                                                                                    return v
                                                                                                                    end

                                                                                                                    local function writeSavedTotal(n)
                                                                                                                    local root = modRoot()
                                                                                                                    if not root then return end
                                                                                                                        local f = io.open(root .. "/state.txt", "w") or io.open(root .. "\\state.txt", "w")
                                                                                                                        if not f then return end
                                                                                                                            f:write("# Written automatically by MyFirstMod to protect items on load.\nSaveMaxSlots = " .. tostring(n) .. "\n")
                                                                                                                            f:close()
                                                                                                                            end

                                                                                                                            loadConfig()

                                                                                                                            -- Target Page Sizes --------------------------------------------------------------------------------
                                                                                                                            local function getTargets()
                                                                                                                            clampConfig()
                                                                                                                            if not cfg.Enabled then
                                                                                                                                return {
                                                                                                                                    [TYPE_ITEMS] = baseDefaults[TYPE_ITEMS],
                                                                                                                                    [TYPE_RUNES] = baseDefaults[TYPE_RUNES],
                                                                                                                                    [TYPE_AMMO]  = baseDefaults[TYPE_AMMO],
                                                                                                                                    [TYPE_QUEST] = baseDefaults[TYPE_QUEST],
                                                                                                                                }
                                                                                                                                end
                                                                                                                                return {
                                                                                                                                    [TYPE_ITEMS] = cfg.BagSlots,
                                                                                                                                    [TYPE_RUNES] = cfg.RuneSlots,
                                                                                                                                    [TYPE_AMMO]  = cfg.AmmoSlots,
                                                                                                                                    [TYPE_QUEST] = cfg.QuestSlots,
                                                                                                                                }
                                                                                                                                end

                                                                                                                                local appliedTargets = getTargets()

                                                                                                                                -- Inventory Layout Reading & Slot Array Growth -----------------------------------------------------
                                                                                                                                local function readLayout(inv)
                                                                                                                                local L = { pages = {} }
                                                                                                                                local ok = pcall(function()
                                                                                                                                local pages = inv.InventoryPages
                                                                                                                                if pages then
                                                                                                                                    local count = #pages
                                                                                                                                    for i = 1, count do
                                                                                                                                        local p = pages[i]
                                                                                                                                        L.pages[i] = { type = num(p.SlotType) or -1, n = num(p.NumSlots) or 0 }
                                                                                                                                        end
                                                                                                                                        end
                                                                                                                                        L.quick = num(inv.NumberOfQuickActionSlots) or 0
                                                                                                                                        L.max = num(inv.MaxSlotCount) or 0
                                                                                                                                        end)
                                                                                                                                if not ok then return nil end
                                                                                                                                    local at = L.quick
                                                                                                                                    for _, p in ipairs(L.pages) do
                                                                                                                                        p.start = at
                                                                                                                                        at = at + p.n
                                                                                                                                        end
                                                                                                                                        L.total = (#L.pages > 0) and at or L.max
                                                                                                                                        return L
                                                                                                                                        end

                                                                                                                                        local function describeLayout(L)
                                                                                                                                        if not L then return "?" end
                                                                                                                                            local t = {}
                                                                                                                                            for _, p in ipairs(L.pages) do
                                                                                                                                                t[#t + 1] = string.format("T%d:%d(%d..%d)", p.type, p.n, p.start, p.start + p.n - 1)
                                                                                                                                                end
                                                                                                                                                return string.format("quick 0..%d | %s | Max=%d", L.quick - 1, table.concat(t, ", "), L.max)
                                                                                                                                                end

                                                                                                                                                local function firstPage(L, t)
                                                                                                                                                for _, p in ipairs(L.pages) do
                                                                                                                                                    if p.type == t then return p end
                                                                                                                                                        end
                                                                                                                                                        return nil
                                                                                                                                                        end

                                                                                                                                                        local function slotTypeAt(L, slotIdx)
                                                                                                                                                        if slotIdx < L.quick then return TYPE_QUICK end
                                                                                                                                                            for _, p in ipairs(L.pages) do
                                                                                                                                                                if slotIdx >= p.start and slotIdx < p.start + p.n then
                                                                                                                                                                    return p.type
                                                                                                                                                                    end
                                                                                                                                                                    end
                                                                                                                                                                    return nil
                                                                                                                                                                    end

                                                                                                                                                                    local function slotsNum(inv)
                                                                                                                                                                    local n
                                                                                                                                                                    pcall(function() n = #inv.ItemSlots end)
                                                                                                                                                                    return num(n)
                                                                                                                                                                    end

                                                                                                                                                                    -- Grows the underlying ItemSlots TArray safely BEFORE MaxSlotCount is manually overwritten
                                                                                                                                                                    local function growSlots(inv, targetSize)
                                                                                                                                                                    local before = slotsNum(inv)
                                                                                                                                                                    if not before or before == 0 or before >= targetSize then return false end
                                                                                                                                                                        -- Call SetMaxSlotCount first while MaxSlotCount is still < targetSize so C++ resizes the TArray
                                                                                                                                                                        pcall(function() inv:SetMaxSlotCount(targetSize) end)
                                                                                                                                                                        local after = slotsNum(inv)
                                                                                                                                                                        if not after or after < targetSize then
                                                                                                                                                                            -- Fallback: touching index [targetSize] in UE4SS
                                                                                                                                                                            pcall(function() local _ = inv.ItemSlots[targetSize] end)
                                                                                                                                                                            after = slotsNum(inv)
                                                                                                                                                                            end
                                                                                                                                                                            dbg(string.format("ItemSlots array grown: %d -> %s (target %d)", before, tostring(after), targetSize))
                                                                                                                                                                            return (after or 0) >= targetSize
                                                                                                                                                                            end

                                                                                                                                                                            -- Item Helpers -------------------------------------------------------------------------------------
                                                                                                                                                                            local function itemAt(inv, i)
                                                                                                                                                                            local it
                                                                                                                                                                            pcall(function() it = inv:GetItemFromSlot(i) end)
                                                                                                                                                                            if valid(it) then return it end
                                                                                                                                                                                return nil
                                                                                                                                                                                end

                                                                                                                                                                                local function countAt(inv, i)
                                                                                                                                                                                local n = 0
                                                                                                                                                                                pcall(function() n = inv:GetNumItemsInSlot(i) end)
                                                                                                                                                                                return num(n) or 0
                                                                                                                                                                                end

                                                                                                                                                                                local function itemName(item)
                                                                                                                                                                                local s = "?"
                                                                                                                                                                                pcall(function() s = item.ItemData.Name:ToString() end)
                                                                                                                                                                                return s
                                                                                                                                                                                end

                                                                                                                                                                                -- Storage Chest Identification, Compaction & Expansion ---------------------------------------------
                                                                                                                                                                                local storageActorCache = {}
                                                                                                                                                                                local baseChestSlots = 24

                                                                                                                                                                                local function isStorageContainerActor(actor)
                                                                                                                                                                                if not valid(actor) then return false end
                                                                                                                                                                                    local cn = className(actor)
                                                                                                                                                                                    if storageActorCache[cn] ~= nil then return storageActorCache[cn] end

                                                                                                                                                                                        local lower = cn:lower()
                                                                                                                                                                                        -- Reject crafting / processing stations (furnaces, workbenches, kilns, etc.)
                                                                                                                                                                                        for _, w in ipairs(STATION_WORDS) do
                                                                                                                                                                                            if lower:find(w, 1, true) then
                                                                                                                                                                                                storageActorCache[cn] = false
                                                                                                                                                                                                return false
                                                                                                                                                                                                end
                                                                                                                                                                                                end

                                                                                                                                                                                                -- Check if actor has a LinkedInventoryComponent (all linkable chests have this) or matches container words
                                                                                                                                                                                                local isStorage = false
                                                                                                                                                                                                for _, w in ipairs(CONTAINER_WORDS) do
                                                                                                                                                                                                    if lower:find(w, 1, true) then
                                                                                                                                                                                                        isStorage = true
                                                                                                                                                                                                        break
                                                                                                                                                                                                        end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        if not isStorage then
                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                            local lic = actor.LinkedInventoryComponent or actor.BP_Components_LinkedInventory
                                                                                                                                                                                                            if valid(lic) then isStorage = true end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end

                                                                                                                                                                                                            -- Ensure it's a BaseBuildingActor (player-built structure) if not explicitly named chest/crate
                                                                                                                                                                                                            if isStorage then
                                                                                                                                                                                                                local isBuilt = false
                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                local cls = actor:GetClass()
                                                                                                                                                                                                                while valid(cls) and not isBuilt do
                                                                                                                                                                                                                    local n = cls:GetFName():ToString():lower()
                                                                                                                                                                                                                    if n:find("basebuilding", 1, true) or n:find("base_building", 1, true) or n:find("chest", 1, true) then
                                                                                                                                                                                                                        isBuilt = true
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        cls = cls:GetSuperStruct()
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                if not isBuilt then isStorage = false end
                                                                                                                                                                                                                    end

                                                                                                                                                                                                                    storageActorCache[cn] = isStorage
                                                                                                                                                                                                                    return isStorage
                                                                                                                                                                                                                    end

                                                                                                                                                                                                                    local function isStorageChestInventory(inv)
                                                                                                                                                                                                                    if not valid(inv) or className(inv) ~= CHEST_INV_CLASS then return false end
                                                                                                                                                                                                                        if isTemplate(full(inv)) then return false end
                                                                                                                                                                                                                            local allowAdds = true
                                                                                                                                                                                                                            pcall(function() allowAdds = inv.bAllowAdds end)
                                                                                                                                                                                                                            if allowAdds == false then return false end
                                                                                                                                                                                                                                local owner
                                                                                                                                                                                                                                pcall(function() owner = inv:GetOwner() end)
                                                                                                                                                                                                                                if not valid(owner) then return false end
                                                                                                                                                                                                                                    local ghost, preview = false, false
                                                                                                                                                                                                                                    pcall(function() ghost = owner.bIsGhosted == true end)
                                                                                                                                                                                                                                    pcall(function() preview = owner.bIsPreview == true end)
                                                                                                                                                                                                                                    if ghost or preview then return false end
                                                                                                                                                                                                                                        return isStorageContainerActor(owner)
                                                                                                                                                                                                                                        end

                                                                                                                                                                                                                                        -- Relocates any chest items sitting at slot >= wantSlots into free slots < wantSlots
                                                                                                                                                                                                                                        -- so lowering ChestSlots in Mod Menu cleanly shrinks the visible chest grid without losing items.
                                                                                                                                                                                                                                        local function compactChestItems(inv, wantSlots)
                                                                                                                                                                                                                                        local curMax
                                                                                                                                                                                                                                        pcall(function() curMax = inv.MaxSlotCount end)
                                                                                                                                                                                                                                        local maxSlots = math.max(num(curMax) or 0, slotsNum(inv) or 0)
                                                                                                                                                                                                                                        if maxSlots <= wantSlots then return wantSlots end

                                                                                                                                                                                                                                            local owner
                                                                                                                                                                                                                                            pcall(function() owner = inv:GetOwner() end)
                                                                                                                                                                                                                                            local canMove = true
                                                                                                                                                                                                                                            if valid(owner) then
                                                                                                                                                                                                                                                local okAuth, auth = pcall(function() return owner:HasAuthority() end)
                                                                                                                                                                                                                                                if okAuth and auth == false then canMove = false end
                                                                                                                                                                                                                                                    end

                                                                                                                                                                                                                                                    local highestUsed = wantSlots
                                                                                                                                                                                                                                                    for i = wantSlots, maxSlots - 1 do
                                                                                                                                                                                                                                                        if itemAt(inv, i) then
                                                                                                                                                                                                                                                            if canMove then
                                                                                                                                                                                                                                                                local targetSlot = nil
                                                                                                                                                                                                                                                                for j = 0, wantSlots - 1 do
                                                                                                                                                                                                                                                                if not itemAt(inv, j) then
                                                                                                                                                                                                                                                                targetSlot = j
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if targetSlot then
                                                                                                                                                                                                                                                                local qty = countAt(inv, i)
                                                                                                                                                                                                                                                                pcall(function() inv:MoveItem(i, inv, targetSlot, owner, qty) end)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if itemAt(inv, i) then
                                                                                                                                                                                                                                                                highestUsed = i + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return highestUsed
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function desiredChestSlots()
                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then
                                                                                                                                                                                                                                                                return baseChestSlots
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return cfg.ChestSlots
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function applyChestLayout(inv, label)
                                                                                                                                                                                                                                                                if not isStorageChestInventory(inv) then return false end

                                                                                                                                                                                                                                                                local curMax
                                                                                                                                                                                                                                                                pcall(function() curMax = inv.MaxSlotCount end)
                                                                                                                                                                                                                                                                curMax = num(curMax) or 0
                                                                                                                                                                                                                                                                if curMax >= 8 and curMax <= 40 and baseChestSlots == 24 then
                                                                                                                                                                                                                                                                baseChestSlots = curMax
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then return false end

                                                                                                                                                                                                                                                                local want = cfg.ChestSlots
                                                                                                                                                                                                                                                                local curArr = slotsNum(inv) or 0

                                                                                                                                                                                                                                                                -- Never shrink underlying MaxSlotCount below high-water mark so items in high slots are never lost
                                                                                                                                                                                                                                                                local targetMax = math.max(want, curMax, curArr)
                                                                                                                                                                                                                                                                local visibleSlots = compactChestItems(inv, want)

                                                                                                                                                                                                                                                                local L = readLayout(inv)
                                                                                                                                                                                                                                                                local pageChanged = false
                                                                                                                                                                                                                                                                if L and #L.pages > 0 then
                                                                                                                                                                                                                                                                for _, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                if p.n ~= visibleSlots then pageChanged = true end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if curMax >= targetMax and curArr >= targetMax and not pageChanged then
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Grow ItemSlots TArray first before overwriting MaxSlotCount
                                                                                                                                                                                                                                                                growSlots(inv, targetMax)

                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                if inv.MaxSlotCount < targetMax then
                                                                                                                                                                                                                                                                inv.MaxSlotCount = targetMax
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if L and #L.pages > 0 then
                                                                                                                                                                                                                                                                for i, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                if p.n ~= visibleSlots then
                                                                                                                                                                                                                                                                inv.InventoryPages[i].NumSlots = visibleSlots
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                local owner
                                                                                                                                                                                                                                                                pcall(function() owner = inv:GetOwner() end)
                                                                                                                                                                                                                                                                log(string.format("%s chest (%s): Visible=%d, MaxSlotCount %d -> %s (ItemSlots: %s)",
                                                                                                                                                                                                                                                                label or "Storage", className(owner), visibleSlots, curMax, tostring(inv.MaxSlotCount), tostring(slotsNum(inv))))
                                                                                                                                                                                                                                                                return true
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Template Patching (CDO + GEN_VARIABLE) -----------------------------------------------------------
                                                                                                                                                                                                                                                                local templateRecorded = false
                                                                                                                                                                                                                                                                local function recordBaseDefaults(L)
                                                                                                                                                                                                                                                                if templateRecorded or not L or #L.pages == 0 then return end
                                                                                                                                                                                                                                                                templateRecorded = true
                                                                                                                                                                                                                                                                baseDefaults.quick = L.quick
                                                                                                                                                                                                                                                                baseDefaults.max = L.max
                                                                                                                                                                                                                                                                for _, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                if p.n >= 8 and p.n <= 96 then
                                                                                                                                                                                                                                                                baseDefaults[p.type] = p.n
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function patchTemplate(t)
                                                                                                                                                                                                                                                                local L = readLayout(t)
                                                                                                                                                                                                                                                                if not L or #L.pages == 0 then return end
                                                                                                                                                                                                                                                                recordBaseDefaults(L)

                                                                                                                                                                                                                                                                local targets = getTargets()
                                                                                                                                                                                                                                                                local wantTotal = L.quick
                                                                                                                                                                                                                                                                local changed = false
                                                                                                                                                                                                                                                                for _, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                local w = targets[p.type] or p.n
                                                                                                                                                                                                                                                                if p.n ~= w then changed = true end
                                                                                                                                                                                                                                                                wantTotal = wantTotal + w
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local savedMax = readSavedTotal() or (cfg.Enabled and wantTotal or MAX_POSSIBLE_TOTAL)
                                                                                                                                                                                                                                                                local wantMax = math.max(wantTotal, savedMax, baseDefaults.max)
                                                                                                                                                                                                                                                                if not changed and L.max == wantMax then return end

                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                for i, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                local w = targets[p.type]
                                                                                                                                                                                                                                                                if w and p.n ~= w then
                                                                                                                                                                                                                                                                t.InventoryPages[i].NumSlots = w
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                t.MaxSlotCount = wantMax
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                dbg("Patched template " .. full(t) .. " -> " .. describeLayout(readLayout(t)))
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function patchTemplatesFromInventory(inv)
                                                                                                                                                                                                                                                                local seen = {}
                                                                                                                                                                                                                                                                local function try(o)
                                                                                                                                                                                                                                                                if valid(o) then
                                                                                                                                                                                                                                                                local k = key(o)
                                                                                                                                                                                                                                                                if not seen[k] then
                                                                                                                                                                                                                                                                seen[k] = true
                                                                                                                                                                                                                                                                pcall(patchTemplate, o)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                pcall(function() try(inv:GetClass():GetCDO()) end)
                                                                                                                                                                                                                                                                local name
                                                                                                                                                                                                                                                                pcall(function() name = inv:GetFName():ToString() end)
                                                                                                                                                                                                                                                                local outer
                                                                                                                                                                                                                                                                pcall(function() outer = inv:GetOuter() end)
                                                                                                                                                                                                                                                                if name and valid(outer) then
                                                                                                                                                                                                                                                                local cls
                                                                                                                                                                                                                                                                pcall(function() cls = outer:GetClass() end)
                                                                                                                                                                                                                                                                for _ = 1, 8 do
                                                                                                                                                                                                                                                                if not valid(cls) then break end
                                                                                                                                                                                                                                                                local cp = pathOf(cls)
                                                                                                                                                                                                                                                                local paths = { cp .. ":" .. name .. "_GEN_VARIABLE" }
                                                                                                                                                                                                                                                                pcall(function() paths[#paths + 1] = pathOf(cls:GetCDO()) .. "." .. name end)
                                                                                                                                                                                                                                                                for _, p in ipairs(paths) do
                                                                                                                                                                                                                                                                local o
                                                                                                                                                                                                                                                                pcall(function() o = StaticFindObject(p) end)
                                                                                                                                                                                                                                                                try(o)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local sup
                                                                                                                                                                                                                                                                pcall(function() sup = cls:GetSuperStruct() end)
                                                                                                                                                                                                                                                                cls = sup
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local stdTpl
                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                stdTpl = StaticFindObject("/Game/Gameplay/Character/Player/BP_PlayerController.BP_PlayerController_C:BP_Components_Inventory_GEN_VARIABLE")
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                try(stdTpl)
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Applying Layout to Live Player Inventory ---------------------------------------------------------
                                                                                                                                                                                                                                                                local function applyInventoryLayout(inv, label)
                                                                                                                                                                                                                                                                local L = readLayout(inv)
                                                                                                                                                                                                                                                                if not L or #L.pages == 0 then return false end
                                                                                                                                                                                                                                                                recordBaseDefaults(L)

                                                                                                                                                                                                                                                                local targets = getTargets()
                                                                                                                                                                                                                                                                local wantTotal = L.quick
                                                                                                                                                                                                                                                                local anyPageDiff = false
                                                                                                                                                                                                                                                                for _, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                local w = targets[p.type] or p.n
                                                                                                                                                                                                                                                                if p.n ~= w then anyPageDiff = true end
                                                                                                                                                                                                                                                                wantTotal = wantTotal + w
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local savedMax = readSavedTotal() or wantTotal
                                                                                                                                                                                                                                                                local curSlots = slotsNum(inv) or 0
                                                                                                                                                                                                                                                                local wantMax = math.max(wantTotal, savedMax, L.max, curSlots)

                                                                                                                                                                                                                                                                if not anyPageDiff and L.max >= wantMax and curSlots >= wantMax then
                                                                                                                                                                                                                                                                appliedTargets = targets
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Grow ItemSlots TArray first while MaxSlotCount is still at its old value
                                                                                                                                                                                                                                                                growSlots(inv, wantMax)

                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                if inv.MaxSlotCount < wantMax then
                                                                                                                                                                                                                                                                inv.MaxSlotCount = wantMax
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                for i, p in ipairs(L.pages) do
                                                                                                                                                                                                                                                                local w = targets[p.type]
                                                                                                                                                                                                                                                                if w and p.n ~= w then
                                                                                                                                                                                                                                                                inv.InventoryPages[i].NumSlots = w
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                appliedTargets = targets
                                                                                                                                                                                                                                                                local after = readLayout(inv)
                                                                                                                                                                                                                                                                log(string.format("%s layout updated: %s -> %s (ItemSlots: %s)",
                                                                                                                                                                                                                                                                label or "Inventory", describeLayout(L), describeLayout(after), tostring(slotsNum(inv))))
                                                                                                                                                                                                                                                                return true
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Item Category Detection & Smart Multi-Tab Relocation ---------------------------------------------
                                                                                                                                                                                                                                                                local function hasTag(tags, prefix)
                                                                                                                                                                                                                                                                for _, t in ipairs(tags) do
                                                                                                                                                                                                                                                                if t == prefix or t:sub(1, #prefix + 1) == prefix .. "." then
                                                                                                                                                                                                                                                                return true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function itemPageType(item)
                                                                                                                                                                                                                                                                local tags = {}
                                                                                                                                                                                                                                                                local ok = pcall(function()
                                                                                                                                                                                                                                                                local arr = item.ItemData.ItemFilterTags.GameplayTags
                                                                                                                                                                                                                                                                for i = 1, #arr do
                                                                                                                                                                                                                                                                tags[#tags + 1] = arr[i].TagName:ToString()
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                if not ok then return nil end
                                                                                                                                                                                                                                                                if hasTag(tags, "ItemFilter.Type.Equipment.Ammo.Rune") then return TYPE_RUNES end
                                                                                                                                                                                                                                                                if hasTag(tags, "ItemFilter.Type.Equipment.Ammo.Arrow") or hasTag(tags, "ItemFilter.Type.Equipment.Ammo.Bolt") then
                                                                                                                                                                                                                                                                return TYPE_AMMO
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if hasTag(tags, "ItemFilter.Type.QuestItem") then return TYPE_QUEST end
                                                                                                                                                                                                                                                                if hasTag(tags, "ItemFilter.Type.Mount") then return nil end
                                                                                                                                                                                                                                                                return TYPE_ITEMS
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Relocates any item sitting in the wrong tab range (or beyond the active pages) into a free slot
                                                                                                                                                                                                                                                                -- of its proper tab, automatically breaking swap deadlocks if two full tabs hold each other's items.
                                                                                                                                                                                                                                                                local function relocateItems(inv, owner)
                                                                                                                                                                                                                                                                local L = readLayout(inv)
                                                                                                                                                                                                                                                                if not L or #L.pages == 0 then return end
                                                                                                                                                                                                                                                                if not valid(owner) then
                                                                                                                                                                                                                                                                pcall(function() owner = inv:GetOwner() end)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local okAuth, auth = pcall(function() return owner:HasAuthority() end)
                                                                                                                                                                                                                                                                if okAuth and auth == false then
                                                                                                                                                                                                                                                                dbg("Client in multiplayer session; skipping authority-only MoveItem relocation.")
                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local last = math.max(L.max, L.total, slotsNum(inv) or 0) - 1
                                                                                                                                                                                                                                                                local moved, stuck = 0, 0

                                                                                                                                                                                                                                                                for _ = 1, 8 do
                                                                                                                                                                                                                                                                local progress = false
                                                                                                                                                                                                                                                                stuck = 0
                                                                                                                                                                                                                                                                for i = L.quick, last do
                                                                                                                                                                                                                                                                local it = itemAt(inv, i)
                                                                                                                                                                                                                                                                if it then
                                                                                                                                                                                                                                                                local wantType = itemPageType(it)
                                                                                                                                                                                                                                                                local curType = slotTypeAt(L, i)
                                                                                                                                                                                                                                                                if wantType ~= nil and curType ~= wantType then
                                                                                                                                                                                                                                                                local page = firstPage(L, wantType)
                                                                                                                                                                                                                                                                local targetSlot = nil
                                                                                                                                                                                                                                                                local isSwap = false

                                                                                                                                                                                                                                                                if page then
                                                                                                                                                                                                                                                                -- 1. Prefer an empty slot in the target tab
                                                                                                                                                                                                                                                                for j = page.start, page.start + page.n - 1 do
                                                                                                                                                                                                                                                                if not itemAt(inv, j) then
                                                                                                                                                                                                                                                                targetSlot = j
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                -- 2. Swap-deadlock breaker: find a slot in the target tab occupied by a wrong-tab item
                                                                                                                                                                                                                                                                if not targetSlot then
                                                                                                                                                                                                                                                                for j = page.start, page.start + page.n - 1 do
                                                                                                                                                                                                                                                                local occ = itemAt(inv, j)
                                                                                                                                                                                                                                                                if occ and itemPageType(occ) ~= wantType then
                                                                                                                                                                                                                                                                targetSlot = j
                                                                                                                                                                                                                                                                isSwap = true
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if targetSlot then
                                                                                                                                                                                                                                                                local qty = countAt(inv, i)
                                                                                                                                                                                                                                                                local prevAddr = nil
                                                                                                                                                                                                                                                                pcall(function() prevAddr = it:GetAddress() end)

                                                                                                                                                                                                                                                                local didMove = false
                                                                                                                                                                                                                                                                if not isSwap then
                                                                                                                                                                                                                                                                local okMove = pcall(function()
                                                                                                                                                                                                                                                                inv:MoveItem(i, inv, targetSlot, owner, qty)
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                if okMove and itemAt(inv, targetSlot) and not itemAt(inv, i) then
                                                                                                                                                                                                                                                                didMove = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                -- Try direct MoveItem swap first
                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                inv:MoveItem(i, inv, targetSlot, owner, qty)
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                local nowAtTarget = itemAt(inv, targetSlot)
                                                                                                                                                                                                                                                                local newAddr = nil
                                                                                                                                                                                                                                                                if nowAtTarget then pcall(function() newAddr = nowAtTarget:GetAddress() end) end
                                                                                                                                                                                                                                                                if newAddr and prevAddr and newAddr == prevAddr then
                                                                                                                                                                                                                                                                didMove = true
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                -- Fallback 3-way swap via any free buffer slot
                                                                                                                                                                                                                                                                local bufSlot = nil
                                                                                                                                                                                                                                                                for b = last, L.quick, -1 do
                                                                                                                                                                                                                                                                if not itemAt(inv, b) then
                                                                                                                                                                                                                                                                bufSlot = b
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if bufSlot then
                                                                                                                                                                                                                                                                local occQty = countAt(inv, targetSlot)
                                                                                                                                                                                                                                                                pcall(function() inv:MoveItem(targetSlot, inv, bufSlot, owner, occQty) end)
                                                                                                                                                                                                                                                                if not itemAt(inv, targetSlot) then
                                                                                                                                                                                                                                                                pcall(function() inv:MoveItem(i, inv, targetSlot, owner, qty) end)
                                                                                                                                                                                                                                                                if not itemAt(inv, i) then
                                                                                                                                                                                                                                                                pcall(function() inv:MoveItem(bufSlot, inv, i, owner, occQty) end)
                                                                                                                                                                                                                                                                didMove = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if didMove then
                                                                                                                                                                                                                                                                moved = moved + 1
                                                                                                                                                                                                                                                                progress = true
                                                                                                                                                                                                                                                                dbg(string.format("Relocated %s x%d: slot %d -> %d (tab %d%s)",
                                                                                                                                                                                                                                                                itemName(it), qty, i, targetSlot, wantType, isSwap and ", swapped" or ""))
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                stuck = stuck + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                stuck = stuck + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if not progress then break end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Check if any items remain past L.total so we can safely shrink MaxSlotCount in state.txt
                                                                                                                                                                                                                                                                local highestUsed = L.total
                                                                                                                                                                                                                                                                for i = L.total, last do
                                                                                                                                                                                                                                                                if itemAt(inv, i) then
                                                                                                                                                                                                                                                                highestUsed = i + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                writeSavedTotal(math.max(L.total, highestUsed))

                                                                                                                                                                                                                                                                if moved > 0 or stuck > 0 then
                                                                                                                                                                                                                                                                log(string.format("Item relocation complete: %d stack(s) moved to their proper tab, %d unable to move%s",
                                                                                                                                                                                                                                                                moved, stuck, stuck > 0 and " (target tab is full!)" or ""))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- UI Grid Resizing, Partial-Row Hiding & Scroll Fixing ---------------------------------------------
                                                                                                                                                                                                                                                                local bodySigCache = {}
                                                                                                                                                                                                                                                                local rebuildAllowedAt = nil

                                                                                                                                                                                                                                                                local function fixScrollChain(body)
                                                                                                                                                                                                                                                                local w = body
                                                                                                                                                                                                                                                                local scrollVis = cfg.HideScrollBar and VIS_COLLAPSED or VIS_VISIBLE
                                                                                                                                                                                                                                                                for _ = 1, 20 do
                                                                                                                                                                                                                                                                local parent
                                                                                                                                                                                                                                                                pcall(function() parent = w:GetParent() end)
                                                                                                                                                                                                                                                                if not valid(parent) then break end
                                                                                                                                                                                                                                                                local cn = className(parent)
                                                                                                                                                                                                                                                                if cn == "ScrollBox" then
                                                                                                                                                                                                                                                                pcall(function() parent:SetScrollBarVisibility(scrollVis) end)
                                                                                                                                                                                                                                                                break
                                                                                                                                                                                                                                                                elseif cn == "ScaleBox" then
                                                                                                                                                                                                                                                                local st
                                                                                                                                                                                                                                                                pcall(function() st = parent.Stretch end)
                                                                                                                                                                                                                                                                if st ~= nil and st ~= 0 and st ~= 3 then
                                                                                                                                                                                                                                                                pcall(function() parent:SetStretch(3) end) -- EStretch::ScaleToFitX
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                elseif cn == "SizeBox" then
                                                                                                                                                                                                                                                                pcall(function() parent:ClearHeightOverride() end)
                                                                                                                                                                                                                                                                pcall(function() parent:ClearMaxDesiredHeight() end)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                w = parent
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function isChestBodyWidget(body)
                                                                                                                                                                                                                                                                local f = full(body)
                                                                                                                                                                                                                                                                if f:find("WorldActor", 1, true) then return true end
                                                                                                                                                                                                                                                                local cn = className(body)
                                                                                                                                                                                                                                                                if cn:find("WorldActor", 1, true) then return true end
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function resolveBodyType(body)
                                                                                                                                                                                                                                                                if isChestBodyWidget(body) then return "chest" end
                                                                                                                                                                                                                                                                local st
                                                                                                                                                                                                                                                                pcall(function() st = body.SlotType end)
                                                                                                                                                                                                                                                                if type(st) == "number" and appliedTargets[st] then return st end
                                                                                                                                                                                                                                                                local n = full(body)
                                                                                                                                                                                                                                                                if n:find("Rune", 1, true) then return TYPE_RUNES end
                                                                                                                                                                                                                                                                if n:find("Ammo", 1, true) or n:find("Ammunition", 1, true) then return TYPE_AMMO end
                                                                                                                                                                                                                                                                if n:find("Quest", 1, true) then return TYPE_QUEST end
                                                                                                                                                                                                                                                                if n:find("Item", 1, true) then return TYPE_ITEMS end
                                                                                                                                                                                                                                                                return nil
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function currentOpenChestSlots()
                                                                                                                                                                                                                                                                local target = desiredChestSlots()
                                                                                                                                                                                                                                                                local ok, api = pcall(FindFirstOf, "WorldActorInventoryUIAPI")
                                                                                                                                                                                                                                                                if ok and valid(api) then
                                                                                                                                                                                                                                                                local inv
                                                                                                                                                                                                                                                                pcall(function() inv = api.InventoryComponent end)
                                                                                                                                                                                                                                                                if valid(inv) and isStorageChestInventory(inv) then
                                                                                                                                                                                                                                                                if cfg.Enabled and cfg.ChestEnabled then
                                                                                                                                                                                                                                                                applyChestLayout(inv, "Open")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return compactChestItems(inv, target)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then return nil end
                                                                                                                                                                                                                                                                return target
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function updateBodyWidget(body, allowRebuild, forceRebuild)
                                                                                                                                                                                                                                                                if not valid(body) then return end
                                                                                                                                                                                                                                                                local f = full(body)
                                                                                                                                                                                                                                                                if isTemplate(f) then return end

                                                                                                                                                                                                                                                                local st = resolveBodyType(body)
                                                                                                                                                                                                                                                                if not st then return end

                                                                                                                                                                                                                                                                local wantSlots
                                                                                                                                                                                                                                                                if st == "chest" then
                                                                                                                                                                                                                                                                wantSlots = currentOpenChestSlots()
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                wantSlots = appliedTargets[st]
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if not wantSlots then return end

                                                                                                                                                                                                                                                                local wantRows = math.ceil(wantSlots / COLUMNS)
                                                                                                                                                                                                                                                                local curRows
                                                                                                                                                                                                                                                                pcall(function() curRows = body.RowCount end)
                                                                                                                                                                                                                                                                local builtCount
                                                                                                                                                                                                                                                                pcall(function() builtCount = #body.InventorySlots end)
                                                                                                                                                                                                                                                                local bk = key(body)
                                                                                                                                                                                                                                                                local sig = string.format("%s/%s/%d/%s", tostring(curRows), tostring(builtCount), wantSlots, tostring(cfg.HideScrollBar))

                                                                                                                                                                                                                                                                if not forceRebuild and curRows == wantRows and bodySigCache[bk] == sig then
                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if curRows ~= wantRows or forceRebuild then
                                                                                                                                                                                                                                                                pcall(function() body.RowCount = wantRows end)
                                                                                                                                                                                                                                                                local canRebuild = allowRebuild and (st == "chest" or (rebuildAllowedAt and os.clock() >= rebuildAllowedAt))
                                                                                                                                                                                                                                                                if canRebuild then
                                                                                                                                                                                                                                                                local grid, cls
                                                                                                                                                                                                                                                                pcall(function() grid = body.SlotGridContainer end)
                                                                                                                                                                                                                                                                pcall(function() cls = body.InventorySlotWidgetRef end)
                                                                                                                                                                                                                                                                if valid(grid) and valid(cls) and type(builtCount) == "number" and builtCount > 0 then
                                                                                                                                                                                                                                                                dbg(string.format("Rebuilding UI grid (%s): %s -> %d rows (%d slots)",
                                                                                                                                                                                                                                                                tostring(st), tostring(curRows), wantRows, wantSlots))
                                                                                                                                                                                                                                                                pcall(function() body.InventorySlots:Empty() end)
                                                                                                                                                                                                                                                                pcall(function() body:InitializeContent() end)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Hide trailing slot widgets on the last row if wantSlots is not a multiple of 8
                                                                                                                                                                                                                                                                local filtering = false
                                                                                                                                                                                                                                                                if st == TYPE_ITEMS then
                                                                                                                                                                                                                                                                filtering = (getShared("InventoryFilters.Active") == true)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if not filtering then
                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                local slots = body.InventorySlots
                                                                                                                                                                                                                                                                for i = 1, #slots do
                                                                                                                                                                                                                                                                local wdg = slots[i]
                                                                                                                                                                                                                                                                if valid(wdg) then
                                                                                                                                                                                                                                                                local wantVis = (i <= wantSlots) and VIS_VISIBLE or VIS_COLLAPSED
                                                                                                                                                                                                                                                                local curVis
                                                                                                                                                                                                                                                                pcall(function() curVis = wdg:GetVisibility() end)
                                                                                                                                                                                                                                                                if wantVis == VIS_COLLAPSED and curVis ~= VIS_COLLAPSED then
                                                                                                                                                                                                                                                                wdg:SetVisibility(VIS_COLLAPSED)
                                                                                                                                                                                                                                                                elseif wantVis == VIS_VISIBLE and curVis == VIS_COLLAPSED then
                                                                                                                                                                                                                                                                wdg:SetVisibility(VIS_VISIBLE)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                fixScrollChain(body)

                                                                                                                                                                                                                                                                local nowCount, nowRows
                                                                                                                                                                                                                                                                pcall(function() nowCount = #body.InventorySlots end)
                                                                                                                                                                                                                                                                pcall(function() nowRows = body.RowCount end)
                                                                                                                                                                                                                                                                bodySigCache[bk] = string.format("%s/%s/%d/%s", tostring(nowRows), tostring(nowCount), wantSlots, tostring(cfg.HideScrollBar))
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function patchBodyTemplates()
                                                                                                                                                                                                                                                                local ok, list = pcall(FindAllOf, "MainInventoryBodyBase")
                                                                                                                                                                                                                                                                if not ok or type(list) ~= "table" then return end
                                                                                                                                                                                                                                                                for _, o in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(o) and isTemplate(full(o)) then
                                                                                                                                                                                                                                                                local st = resolveBodyType(o)
                                                                                                                                                                                                                                                                local wantSlots = nil
                                                                                                                                                                                                                                                                if st == "chest" then
                                                                                                                                                                                                                                                                if cfg.Enabled and cfg.ChestEnabled then wantSlots = cfg.ChestSlots end
                                                                                                                                                                                                                                                                elseif st then
                                                                                                                                                                                                                                                                wantSlots = appliedTargets[st]
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if wantSlots then
                                                                                                                                                                                                                                                                local wantRows = math.ceil(wantSlots / COLUMNS)
                                                                                                                                                                                                                                                                local curRows
                                                                                                                                                                                                                                                                pcall(function() curRows = o.RowCount end)
                                                                                                                                                                                                                                                                if curRows ~= wantRows then
                                                                                                                                                                                                                                                                pcall(function() o.RowCount = wantRows end)
                                                                                                                                                                                                                                                                dbg(string.format("Patched grid template %s: %s -> %d rows", full(o), tostring(curRows), wantRows))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Hot-Reload Safe Item Weight Scaling / Zeroing ----------------------------------------------------
                                                                                                                                                                                                                                                                local origWeights = {}
                                                                                                                                                                                                                                                                local lastWeightSig = nil
                                                                                                                                                                                                                                                                local nextWeightScan = 0
                                                                                                                                                                                                                                                                local weightScans = 0
                                                                                                                                                                                                                                                                local newItemCreatedAt = nil

                                                                                                                                                                                                                                                                local function currentWeightFactor()
                                                                                                                                                                                                                                                                if not cfg.Enabled then return 1.0 end
                                                                                                                                                                                                                                                                if cfg.NoWeight then return 0.0 end
                                                                                                                                                                                                                                                                return cfg.WeightScale
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Retrieves and caches the true vanilla weight in UE4SS shared variables so Ctrl+R reloads
                                                                                                                                                                                                                                                                -- never compound scaled weights or lose original weights when NoWeight is active.
                                                                                                                                                                                                                                                                local function getOrRecordOrigWeight(d, curW)
                                                                                                                                                                                                                                                                local p = pathOf(d)
                                                                                                                                                                                                                                                                if p == "" then return nil end
                                                                                                                                                                                                                                                                if origWeights[p] ~= nil then return origWeights[p] end

                                                                                                                                                                                                                                                                local sharedKey = "MyFirstMod.OrigWeight." .. p
                                                                                                                                                                                                                                                                local saved = getShared(sharedKey)
                                                                                                                                                                                                                                                                if type(saved) == "number" and saved > 0 then
                                                                                                                                                                                                                                                                origWeights[p] = saved
                                                                                                                                                                                                                                                                return saved
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if type(curW) == "number" and curW > 0 then
                                                                                                                                                                                                                                                                origWeights[p] = curW
                                                                                                                                                                                                                                                                setShared(sharedKey, curW)
                                                                                                                                                                                                                                                                return curW
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return nil
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function applyWeights(forceNow)
                                                                                                                                                                                                                                                                local factor = currentWeightFactor()
                                                                                                                                                                                                                                                                if lastWeightSig ~= nil and factor ~= lastWeightSig then
                                                                                                                                                                                                                                                                forceNow = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                lastWeightSig = factor

                                                                                                                                                                                                                                                                if newItemCreatedAt and os.clock() - newItemCreatedAt >= 2.0 then
                                                                                                                                                                                                                                                                newItemCreatedAt = nil
                                                                                                                                                                                                                                                                forceNow = true
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local weightsWereModified = (getShared("MyFirstMod.WeightsModified") == true)

                                                                                                                                                                                                                                                                if not forceNow then
                                                                                                                                                                                                                                                                if factor == 1.0 and next(origWeights) == nil and not weightsWereModified then return end
                                                                                                                                                                                                                                                                if weightScans >= 3 or os.clock() < nextWeightScan then return end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if forceNow then
                                                                                                                                                                                                                                                                weightScans = 0
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                weightScans = weightScans + 1
                                                                                                                                                                                                                                                                nextWeightScan = os.clock() + (weightScans == 1 and 20 or 45)

                                                                                                                                                                                                                                                                local ok, list = pcall(FindAllOf, "ItemData")
                                                                                                                                                                                                                                                                if not ok or type(list) ~= "table" then return end

                                                                                                                                                                                                                                                                if factor == 1.0 then
                                                                                                                                                                                                                                                                local restored = 0
                                                                                                                                                                                                                                                                for _, d in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(d) then
                                                                                                                                                                                                                                                                local p = pathOf(d)
                                                                                                                                                                                                                                                                if p ~= "" and not p:find("Default__", 1, true) then
                                                                                                                                                                                                                                                                local orig = origWeights[p] or getShared("MyFirstMod.OrigWeight." .. p)
                                                                                                                                                                                                                                                                if type(orig) == "number" and orig > 0 then
                                                                                                                                                                                                                                                                local curW
                                                                                                                                                                                                                                                                pcall(function() curW = d.Weight end)
                                                                                                                                                                                                                                                                if type(curW) == "number" and math.abs(curW - orig) > 0.0001 then
                                                                                                                                                                                                                                                                pcall(function() d.Weight = orig end)
                                                                                                                                                                                                                                                                restored = restored + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                origWeights = {}
                                                                                                                                                                                                                                                                setShared("MyFirstMod.WeightsModified", false)
                                                                                                                                                                                                                                                                if restored > 0 then
                                                                                                                                                                                                                                                                log(string.format("Restored original weight on %d item type(s).", restored))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local updated = 0
                                                                                                                                                                                                                                                                for _, d in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(d) then
                                                                                                                                                                                                                                                                local fName = full(d)
                                                                                                                                                                                                                                                                if not fName:find("Default__", 1, true) then
                                                                                                                                                                                                                                                                local w
                                                                                                                                                                                                                                                                pcall(function() w = d.Weight end)
                                                                                                                                                                                                                                                                if type(w) == "number" then
                                                                                                                                                                                                                                                                local baseW = getOrRecordOrigWeight(d, w)
                                                                                                                                                                                                                                                                if baseW and baseW > 0 then
                                                                                                                                                                                                                                                                local targetW = baseW * factor
                                                                                                                                                                                                                                                                if math.abs(w - targetW) > 0.0001 then
                                                                                                                                                                                                                                                                pcall(function() d.Weight = targetW end)
                                                                                                                                                                                                                                                                updated = updated + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                setShared("MyFirstMod.WeightsModified", true)
                                                                                                                                                                                                                                                                if updated > 0 then
                                                                                                                                                                                                                                                                log(string.format("Weight multiplier (%.1fx) applied to %d item type(s).", factor, updated))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                pcall(NotifyOnNewObject, "/Script/Dominion.ItemData", function()
                                                                                                                                                                                                                                                                if currentWeightFactor() < 1.0 then
                                                                                                                                                                                                                                                                newItemCreatedAt = os.clock()
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                -- Tracked Live Objects & Search Window Management --------------------------------------------------
                                                                                                                                                                                                                                                                local trackedInv = {}
                                                                                                                                                                                                                                                                local trackedChests = {}
                                                                                                                                                                                                                                                                local trackedBody = {}
                                                                                                                                                                                                                                                                local checkedInv = {}
                                                                                                                                                                                                                                                                local loadedAt = {}
                                                                                                                                                                                                                                                                local stableCount = {}

                                                                                                                                                                                                                                                                local nextInvSearch, nextChestSearch, nextBodySearch = 0, 0, 0
                                                                                                                                                                                                                                                                local SEARCH_UNTIL = os.clock() + 180

                                                                                                                                                                                                                                                                local function extendSearchWindow(secs)
                                                                                                                                                                                                                                                                local target = os.clock() + (secs or 90)
                                                                                                                                                                                                                                                                if target > SEARCH_UNTIL then
                                                                                                                                                                                                                                                                SEARCH_UNTIL = target
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function wakeTracked(tracked, secs)
                                                                                                                                                                                                                                                                local till = os.clock() + secs
                                                                                                                                                                                                                                                                for _, r in pairs(tracked) do
                                                                                                                                                                                                                                                                r.active = till
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function getLiveObjects(tracked, cls, nextAt)
                                                                                                                                                                                                                                                                local list = {}
                                                                                                                                                                                                                                                                local now = os.clock()
                                                                                                                                                                                                                                                                local anyKnown = false
                                                                                                                                                                                                                                                                for k, r in pairs(tracked) do
                                                                                                                                                                                                                                                                local o = deref(r)
                                                                                                                                                                                                                                                                if not o then
                                                                                                                                                                                                                                                                tracked[k] = nil
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                anyKnown = true
                                                                                                                                                                                                                                                                local due = (not r.active) or (now < r.active)
                                                                                                                                                                                                                                                                if not due and r.slow and now >= (r.slowAt or 0) then
                                                                                                                                                                                                                                                                due = true
                                                                                                                                                                                                                                                                r.slowAt = now + r.slow
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if due then
                                                                                                                                                                                                                                                                list[#list + 1] = o
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if anyKnown or now < nextAt or now > SEARCH_UNTIL then
                                                                                                                                                                                                                                                                return list, nextAt
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local ok, found = pcall(FindAllOf, cls)
                                                                                                                                                                                                                                                                for _, o in ipairs((ok and type(found) == "table") and found or {}) do
                                                                                                                                                                                                                                                                if valid(o) and not isTemplate(full(o)) then
                                                                                                                                                                                                                                                                local r = ref(o)
                                                                                                                                                                                                                                                                r.active = now + 30
                                                                                                                                                                                                                                                                r.slow = 10
                                                                                                                                                                                                                                                                tracked[key(o)] = r
                                                                                                                                                                                                                                                                list[#list + 1] = o
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                return list, now + 10
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function expandAllLoadedChests(label)
                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then return end
                                                                                                                                                                                                                                                                local ok, chests = pcall(FindAllOf, CHEST_INV_CLASS)
                                                                                                                                                                                                                                                                if not ok or type(chests) ~= "table" then return end
                                                                                                                                                                                                                                                                local count = 0
                                                                                                                                                                                                                                                                for _, c in ipairs(chests) do
                                                                                                                                                                                                                                                                if valid(c) and not isTemplate(full(c)) then
                                                                                                                                                                                                                                                                trackedChests[key(c)] = { path = pathOf(c), addr = c:GetAddress(), active = os.clock() + 15, slow = 20 }
                                                                                                                                                                                                                                                                if applyChestLayout(c, label or "World") then
                                                                                                                                                                                                                                                                count = count + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if count > 0 then
                                                                                                                                                                                                                                                                log(string.format("Updated %d storage chest(s) (target: %d slots).", count, cfg.ChestSlots))
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Live Apply All Function (Called from Mod Menu, Hotkey, or World Load) ----------------------------
                                                                                                                                                                                                                                                                local function applyAllLive(reason)
                                                                                                                                                                                                                                                                clampConfig()
                                                                                                                                                                                                                                                                appliedTargets = getTargets()
                                                                                                                                                                                                                                                                extendSearchWindow(90)

                                                                                                                                                                                                                                                                log(string.format("Applying (%s) -> Enabled=%s | Bag=%d, Runes=%d, Ammo=%d, Quest=%d | Chests=%s (%d) | NoWeight=%s (%.1fx)",
                                                                                                                                                                                                                                                                reason or "manual", tostring(cfg.Enabled),
                                                                                                                                                                                                                                                                appliedTargets[TYPE_ITEMS], appliedTargets[TYPE_RUNES],
                                                                                                                                                                                                                                                                appliedTargets[TYPE_AMMO], appliedTargets[TYPE_QUEST],
                                                                                                                                                                                                                                                                tostring(cfg.ChestEnabled), cfg.ChestSlots,
                                                                                                                                                                                                                                                                tostring(cfg.NoWeight), cfg.WeightScale))

                                                                                                                                                                                                                                                                -- 1. Wake tracked objects & refresh if needed
                                                                                                                                                                                                                                                                wakeTracked(trackedInv, 30)
                                                                                                                                                                                                                                                                wakeTracked(trackedChests, 30)
                                                                                                                                                                                                                                                                wakeTracked(trackedBody, 30)
                                                                                                                                                                                                                                                                nextInvSearch, nextChestSearch, nextBodySearch = 0, 0, 0

                                                                                                                                                                                                                                                                -- 2. Update live player inventories & relocate any items whose page boundaries shifted
                                                                                                                                                                                                                                                                local invs = getLiveObjects(trackedInv, PLAYER_INV_CLASS, 0)
                                                                                                                                                                                                                                                                for _, inv in ipairs(invs) do
                                                                                                                                                                                                                                                                if valid(inv) and not isTemplate(full(inv)) then
                                                                                                                                                                                                                                                                patchTemplatesFromInventory(inv)
                                                                                                                                                                                                                                                                applyInventoryLayout(inv, "Live player")
                                                                                                                                                                                                                                                                local loaded
                                                                                                                                                                                                                                                                pcall(function() loaded = inv.bHasLoadedFromSave end)
                                                                                                                                                                                                                                                                if loaded == true then
                                                                                                                                                                                                                                                                pcall(relocateItems, inv)
                                                                                                                                                                                                                                                                rebuildAllowedAt = os.clock()
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- 3. Expand or compact all loaded storage chests
                                                                                                                                                                                                                                                                pcall(expandAllLoadedChests, "Live")

                                                                                                                                                                                                                                                                -- 4. Patch UI templates & rebuild active UI grids
                                                                                                                                                                                                                                                                pcall(patchBodyTemplates)
                                                                                                                                                                                                                                                                bodySigCache = {}
                                                                                                                                                                                                                                                                local bodies = getLiveObjects(trackedBody, "MainInventoryBodyBase", 0)
                                                                                                                                                                                                                                                                for _, b in ipairs(bodies) do
                                                                                                                                                                                                                                                                if valid(b) and not isTemplate(full(b)) then
                                                                                                                                                                                                                                                                pcall(updateBodyWidget, b, true, true)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- 5. Update weights immediately
                                                                                                                                                                                                                                                                pcall(applyWeights, true)
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Object Creation Notifications & Chest Open Hook --------------------------------------------------
                                                                                                                                                                                                                                                                local function onNewInventory(obj)
                                                                                                                                                                                                                                                                if not valid(obj) or isTemplate(full(obj)) then return end
                                                                                                                                                                                                                                                                extendSearchWindow(90)
                                                                                                                                                                                                                                                                local cn = className(obj)
                                                                                                                                                                                                                                                                if cn == PLAYER_INV_CLASS then
                                                                                                                                                                                                                                                                local L = readLayout(obj)
                                                                                                                                                                                                                                                                if not L then return end
                                                                                                                                                                                                                                                                local k = key(obj)
                                                                                                                                                                                                                                                                checkedInv[k], loadedAt[k], stableCount[k] = nil, nil, nil
                                                                                                                                                                                                                                                                rebuildAllowedAt = nil

                                                                                                                                                                                                                                                                patchTemplatesFromInventory(obj)
                                                                                                                                                                                                                                                                applyInventoryLayout(obj, "New player")
                                                                                                                                                                                                                                                                pcall(patchBodyTemplates)

                                                                                                                                                                                                                                                                local r = ref(obj)
                                                                                                                                                                                                                                                                r.active = os.clock() + 45
                                                                                                                                                                                                                                                                r.slow = 10
                                                                                                                                                                                                                                                                trackedInv[k] = r
                                                                                                                                                                                                                                                                elseif cn == CHEST_INV_CLASS then
                                                                                                                                                                                                                                                                local r = ref(obj)
                                                                                                                                                                                                                                                                r.active = os.clock() + 30
                                                                                                                                                                                                                                                                r.slow = 20
                                                                                                                                                                                                                                                                trackedChests[key(obj)] = r
                                                                                                                                                                                                                                                                pcall(applyChestLayout, obj, "New")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                pcall(NotifyOnNewObject, "/Script/Dominion.InventoryComponent", function(obj)
                                                                                                                                                                                                                                                                pcall(onNewInventory, obj)
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                pcall(NotifyOnNewObject, "/Script/Dominion.MainInventoryBodyBase", function(obj)
                                                                                                                                                                                                                                                                if not valid(obj) or isTemplate(full(obj)) then return end
                                                                                                                                                                                                                                                                extendSearchWindow(45)
                                                                                                                                                                                                                                                                pcall(patchBodyTemplates)
                                                                                                                                                                                                                                                                local r = ref(obj)
                                                                                                                                                                                                                                                                r.active = os.clock() + 20
                                                                                                                                                                                                                                                                r.slow = 10
                                                                                                                                                                                                                                                                trackedBody[key(obj)] = r
                                                                                                                                                                                                                                                                wakeTracked(trackedBody, 15)
                                                                                                                                                                                                                                                                pcall(updateBodyWidget, obj, false, false)
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                -- Hook when a chest or world container is opened so its slots & UI grid are always ready
                                                                                                                                                                                                                                                                pcall(RegisterHook, "/Script/Dominion.WorldActorInventoryUIAPI:ToggleInventory", function()
                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then return end
                                                                                                                                                                                                                                                                wakeTracked(trackedChests, 15)
                                                                                                                                                                                                                                                                wakeTracked(trackedBody, 15)
                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                local api = FindFirstOf("WorldActorInventoryUIAPI")
                                                                                                                                                                                                                                                                if valid(api) then
                                                                                                                                                                                                                                                                local inv = api.InventoryComponent
                                                                                                                                                                                                                                                                if valid(inv) then
                                                                                                                                                                                                                                                                applyChestLayout(inv, "Opened")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                end)

                                                                                                                                                                                                                                                                -- Periodic Tick (Inventory Enforcer, Save Load Relocation, Chests, UI Grids, Mod Menu Sync) --------
                                                                                                                                                                                                                                                                local function tickInventories()
                                                                                                                                                                                                                                                                local list
                                                                                                                                                                                                                                                                list, nextInvSearch = getLiveObjects(trackedInv, PLAYER_INV_CLASS, nextInvSearch)
                                                                                                                                                                                                                                                                for _, inv in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(inv) and not isTemplate(full(inv)) then
                                                                                                                                                                                                                                                                local k = key(inv)
                                                                                                                                                                                                                                                                if applyInventoryLayout(inv, "Enforced") then
                                                                                                                                                                                                                                                                stableCount[k] = nil
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if not checkedInv[k] then
                                                                                                                                                                                                                                                                local owner
                                                                                                                                                                                                                                                                pcall(function() owner = inv:GetOwner() end)
                                                                                                                                                                                                                                                                local loaded
                                                                                                                                                                                                                                                                pcall(function() loaded = inv.bHasLoadedFromSave end)
                                                                                                                                                                                                                                                                if valid(owner) and loaded == true and not loadedAt[k] then
                                                                                                                                                                                                                                                                loadedAt[k] = os.clock()
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local ready = false
                                                                                                                                                                                                                                                                if valid(owner) and loadedAt[k] then
                                                                                                                                                                                                                                                                local filled = 0
                                                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                                                local mx = num(inv.MaxSlotCount) or 0
                                                                                                                                                                                                                                                                for i = 0, mx - 1 do
                                                                                                                                                                                                                                                                local it = inv:GetItemFromSlot(i)
                                                                                                                                                                                                                                                                if it and it:IsValid() then
                                                                                                                                                                                                                                                                filled = filled + 1
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                local now = os.clock()
                                                                                                                                                                                                                                                                local st = stableCount[k]
                                                                                                                                                                                                                                                                if not st or st.filled ~= filled then
                                                                                                                                                                                                                                                                stableCount[k] = { filled = filled, since = now }
                                                                                                                                                                                                                                                                elseif (filled > 0 and now - st.since >= 2.5)
                                                                                                                                                                                                                                                                or (filled == 0 and now - st.since >= 5.0) then
                                                                                                                                                                                                                                                                ready = true
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if now - loadedAt[k] > 60 then ready = true end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                if ready then
                                                                                                                                                                                                                                                                checkedInv[k] = true
                                                                                                                                                                                                                                                                rebuildAllowedAt = os.clock() + 1.0
                                                                                                                                                                                                                                                                local r = trackedInv[k]
                                                                                                                                                                                                                                                                if r then r.active = os.clock() + 15 end
                                                                                                                                                                                                                                                                wakeTracked(trackedBody, 15)
                                                                                                                                                                                                                                                                pcall(relocateItems, inv, owner)
                                                                                                                                                                                                                                                                pcall(expandAllLoadedChests, "Initial world")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function tickChests()
                                                                                                                                                                                                                                                                if not cfg.Enabled or not cfg.ChestEnabled then return end
                                                                                                                                                                                                                                                                local list
                                                                                                                                                                                                                                                                list, nextChestSearch = getLiveObjects(trackedChests, CHEST_INV_CLASS, nextChestSearch)
                                                                                                                                                                                                                                                                for _, c in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(c) and not isTemplate(full(c)) then
                                                                                                                                                                                                                                                                pcall(applyChestLayout, c, "Tracked")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function tickBodies()
                                                                                                                                                                                                                                                                local list
                                                                                                                                                                                                                                                                list, nextBodySearch = getLiveObjects(trackedBody, "MainInventoryBodyBase", nextBodySearch)
                                                                                                                                                                                                                                                                for _, b in ipairs(list) do
                                                                                                                                                                                                                                                                if valid(b) and not isTemplate(full(b)) then
                                                                                                                                                                                                                                                                pcall(updateBodyWidget, b, true, false)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Dynamic Hotkey Registration ----------------------------------------------------------------------
                                                                                                                                                                                                                                                                local registeredKeys = {}

                                                                                                                                                                                                                                                                local function registerApplyHotkey(keyName)
                                                                                                                                                                                                                                                                local norm = tostring(keyName or "F9"):upper():gsub("^%s+", ""):gsub("%s+$", "")
                                                                                                                                                                                                                                                                if norm == "" then norm = "F9" end
                                                                                                                                                                                                                                                                cfg.Hotkey = norm
                                                                                                                                                                                                                                                                if registeredKeys[norm] then return end

                                                                                                                                                                                                                                                                local bindKey = Key and Key[norm]
                                                                                                                                                                                                                                                                if bindKey then
                                                                                                                                                                                                                                                                local ok = pcall(RegisterKeyBind, bindKey, function()
                                                                                                                                                                                                                                                                if cfg.Hotkey ~= norm then return end
                                                                                                                                                                                                                                                                ExecuteInGameThread(function()
                                                                                                                                                                                                                                                                pcall(applyAllLive, "Hotkey " .. norm)
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                if ok then
                                                                                                                                                                                                                                                                registeredKeys[norm] = true
                                                                                                                                                                                                                                                                dbg("Registered apply hotkey: " .. norm)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Mod Menu 2.0 Live Sync ---------------------------------------------------------------------------
                                                                                                                                                                                                                                                                local mmRev = nil
                                                                                                                                                                                                                                                                local lastAction = nil

                                                                                                                                                                                                                                                                local function getModMenuVar(k)
                                                                                                                                                                                                                                                                return getShared("ModMenu." .. MODMENU_ID .. "." .. k)
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local function syncModMenu()
                                                                                                                                                                                                                                                                local rev = getModMenuVar("rev")
                                                                                                                                                                                                                                                                if type(rev) == "number" and rev ~= mmRev then
                                                                                                                                                                                                                                                                local isInitial = (mmRev == nil)
                                                                                                                                                                                                                                                                mmRev = rev
                                                                                                                                                                                                                                                                local changed = false
                                                                                                                                                                                                                                                                local hotkeyChanged = false
                                                                                                                                                                                                                                                                for k, oldVal in pairs(cfg) do
                                                                                                                                                                                                                                                                local newVal = getModMenuVar(k)
                                                                                                                                                                                                                                                                if newVal ~= nil and type(newVal) == type(oldVal) then
                                                                                                                                                                                                                                                                if cfg[k] ~= newVal then
                                                                                                                                                                                                                                                                changed = true
                                                                                                                                                                                                                                                                if k == "Hotkey" then hotkeyChanged = true end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                cfg[k] = newVal
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                clampConfig()
                                                                                                                                                                                                                                                                if hotkeyChanged then
                                                                                                                                                                                                                                                                registerApplyHotkey(cfg.Hotkey)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if changed then
                                                                                                                                                                                                                                                                pcall(saveConfig)
                                                                                                                                                                                                                                                                applyAllLive(isInitial and "Mod Menu Init" or "Mod Menu")
                                                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                                                appliedTargets = getTargets()
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local action = getModMenuVar("action")
                                                                                                                                                                                                                                                                if action ~= nil and action ~= lastAction then
                                                                                                                                                                                                                                                                lastAction = action
                                                                                                                                                                                                                                                                local actStr = tostring(action)
                                                                                                                                                                                                                                                                if actStr:match("^apply_slots#") or actStr:match("^test_button#") then
                                                                                                                                                                                                                                                                applyAllLive("Mod Menu Button")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Optional Cooperative LuaHeapCleaner Integration --------------------------------------------------
                                                                                                                                                                                                                                                                local heapShield = nil
                                                                                                                                                                                                                                                                local heapShieldChecked = false

                                                                                                                                                                                                                                                                local function stepHeapShield()
                                                                                                                                                                                                                                                                if not heapShieldChecked then
                                                                                                                                                                                                                                                                local sp = getShared("LuaHeapCleaner.ScriptsPath")
                                                                                                                                                                                                                                                                if type(sp) == "string" and sp ~= "" then
                                                                                                                                                                                                                                                                heapShieldChecked = true
                                                                                                                                                                                                                                                                if not package.path:find(sp, 1, true) then
                                                                                                                                                                                                                                                                package.path = package.path .. ";" .. sp
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                local ok, mod = pcall(require, "heap_shield")
                                                                                                                                                                                                                                                                if ok and type(mod) == "table" then
                                                                                                                                                                                                                                                                heapShield = mod
                                                                                                                                                                                                                                                                dbg("Connected to LuaHeapCleaner heap_shield.")
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                if heapShield and heapShield.step then
                                                                                                                                                                                                                                                                pcall(heapShield.step)
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                -- Main Loop & Startup ------------------------------------------------------------------------------
                                                                                                                                                                                                                                                                registerApplyHotkey(cfg.Hotkey)
                                                                                                                                                                                                                                                                pcall(syncModMenu)

                                                                                                                                                                                                                                                                local function mainTick()
                                                                                                                                                                                                                                                                pcall(syncModMenu)
                                                                                                                                                                                                                                                                pcall(tickInventories)
                                                                                                                                                                                                                                                                pcall(tickChests)
                                                                                                                                                                                                                                                                pcall(tickBodies)
                                                                                                                                                                                                                                                                pcall(applyWeights, false)
                                                                                                                                                                                                                                                                stepHeapShield()
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                local okLoop = pcall(LoopInGameThreadWithDelay, 500, mainTick)
                                                                                                                                                                                                                                                                if not okLoop then
                                                                                                                                                                                                                                                                local queued, queuedAt = false, 0
                                                                                                                                                                                                                                                                local function runQueuedTick()
                                                                                                                                                                                                                                                                queued = false
                                                                                                                                                                                                                                                                mainTick()
                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                LoopAsync(500, function()
                                                                                                                                                                                                                                                                if queued and os.clock() - queuedAt > 5 then queued = false end
                                                                                                                                                                                                                                                                if queued then return false end
                                                                                                                                                                                                                                                                queued, queuedAt = true, os.clock()
                                                                                                                                                                                                                                                                local sent = pcall(ExecuteInGameThread, runQueuedTick)
                                                                                                                                                                                                                                                                if not sent then queued = false end
                                                                                                                                                                                                                                                                return false
                                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                                end

                                                                                                                                                                                                                                                                log(string.format("Loaded v%s! Bag=%d, Runes=%d, Ammo=%d, Quest=%d | Chests=%s (%d) | NoWeight=%s (Hotkey: %s)",
                                                                                                                                                                                                                                                                VERSION, cfg.BagSlots, cfg.RuneSlots, cfg.AmmoSlots, cfg.QuestSlots,
                                                                                                                                                                                                                                                                tostring(cfg.ChestEnabled), cfg.ChestSlots, tostring(cfg.NoWeight), tostring(cfg.Hotkey)))
